package com.lolfm.simulator;import java.util.*;
public final class CombatProgressionEvaluator {public CombatProgressionBreakdown evaluate(GameState s,ProgressionCombatContext c,List<PlayerState>own,List<PlayerState>enemy){if(!s.isProgressionPowerEnabled())return new CombatProgressionBreakdown(c,eligible(own,s.getCurrentTimeSeconds()).size(),eligible(enemy,s.getCurrentTimeSeconds()).size(),0,0,0,ProgressionRuleConfig.contextMultiplier(c),0);List<PlayerState>a=eligible(own,s.getCurrentTimeSeconds()),b=eligible(enemy,s.getCurrentTimeSeconds());double ap=avg(a,c),bp=avg(b,c),edge=ap-bp,value=edge*ProgressionRuleConfig.contextMultiplier(c);s.getProgressionExecutionStats().power(c,edge,value);return new CombatProgressionBreakdown(c,a.size(),b.size(),ap,bp,edge,ProgressionRuleConfig.contextMultiplier(c),value);}public double contribution(GameState s,ProgressionCombatContext c,List<PlayerState>a,List<PlayerState>b){return evaluate(s,c,a,b).finalContribution();}private List<PlayerState>eligible(List<PlayerState>x,int t){return x.stream().filter(p->p.isAlive(t)).distinct().toList();}private double avg(List<PlayerState>x,ProgressionCombatContext c){return x.isEmpty()?0:x.stream().mapToDouble(p->new PlayerProgressionPowerEvaluator().evaluate(p,c,true).clampedTotalPower()).average().orElse(0);}}
